/*
 * cli_tool - MNIST model inference
 *
 * Usage: ./cli_tool weights.json image.png
 *
 * Loads model weights from a JSON file, decodes a PNG image,
 * converts it to a normalized 28x28 grayscale MNIST-style input
 * (pixel/255, white digit on black background), runs the MLP
 * (Linear->ReLU->Linear->ReLU->Linear) in float32 and prints the
 * predicted digit (0-9) to stdout.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#include "cJSON.h"
#include "lodepng.h"

#define MNIST_W 28
#define MNIST_H 28
#define MAX_LAYERS 8

typedef struct {
    int in_features;
    int out_features;
    float *weight; /* row-major [out_features][in_features] */
    float *bias;   /* [out_features] */
} Layer;

static char *read_file(const char *path, long *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    if (fseek(f, 0, SEEK_END) != 0) { fclose(f); return NULL; }
    long len = ftell(f);
    if (len < 0) { fclose(f); return NULL; }
    rewind(f);
    char *buf = (char *)malloc((size_t)len + 1);
    if (!buf) { fclose(f); return NULL; }
    if (len > 0 && fread(buf, 1, (size_t)len, f) != (size_t)len) {
        free(buf); fclose(f); return NULL;
    }
    fclose(f);
    buf[len] = '\0';
    if (out_len) *out_len = len;
    return buf;
}

/* Load weights.json into layers. Returns 0 on success. */
static int load_model(const char *path, int *input_dim, int *num_classes,
                      Layer layers[MAX_LAYERS], int *n_layers) {
    long len = 0;
    char *text = read_file(path, &len);
    if (!text) {
        fprintf(stderr, "error: cannot read weights file '%s'\n", path);
        return 1;
    }
    cJSON *root = cJSON_ParseWithLength(text, (size_t)len);
    free(text);
    if (!root) {
        fprintf(stderr, "error: failed to parse JSON in '%s'\n", path);
        return 1;
    }

    /* Model dimensions (optional; inferred from layers if absent). */
    int m_input = 0, m_classes = 0;
    cJSON *model = cJSON_GetObjectItemCaseSensitive(root, "model");
    if (model && cJSON_IsObject(model)) {
        cJSON *j = cJSON_GetObjectItemCaseSensitive(model, "input_dim");
        if (j && cJSON_IsNumber(j)) m_input = (int)j->valuedouble;
        j = cJSON_GetObjectItemCaseSensitive(model, "num_classes");
        if (j && cJSON_IsNumber(j)) m_classes = (int)j->valuedouble;
    }

    cJSON *jlayers = cJSON_GetObjectItemCaseSensitive(root, "layers");
    if (!jlayers || !cJSON_IsArray(jlayers)) {
        fprintf(stderr, "error: weights file missing 'layers' array\n");
        cJSON_Delete(root);
        return 1;
    }
    int n = cJSON_GetArraySize(jlayers);
    if (n <= 0 || n > MAX_LAYERS) {
        fprintf(stderr, "error: unsupported number of layers: %d\n", n);
        cJSON_Delete(root);
        return 1;
    }

    *n_layers = 0;
    for (int li = 0; li < n; li++) {
        cJSON *jl = cJSON_GetArrayItem(jlayers, li);
        if (!jl || !cJSON_IsObject(jl)) goto bad;
        cJSON *jin  = cJSON_GetObjectItemCaseSensitive(jl, "in_features");
        cJSON *jout = cJSON_GetObjectItemCaseSensitive(jl, "out_features");
        cJSON *jw   = cJSON_GetObjectItemCaseSensitive(jl, "weight");
        cJSON *jb   = cJSON_GetObjectItemCaseSensitive(jl, "bias");
        if (!jin || !jout || !jw || !jb ||
            !cJSON_IsNumber(jin) || !cJSON_IsNumber(jout) ||
            !cJSON_IsArray(jw) || !cJSON_IsArray(jb)) goto bad;

        int in_f = (int)jin->valuedouble;
        int out_f = (int)jout->valuedouble;
        if (in_f <= 0 || out_f <= 0) goto bad;
        if (cJSON_GetArraySize(jw) != in_f * out_f) {
            fprintf(stderr, "error: layer %d weight size mismatch\n", li);
            goto bad;
        }
        if (cJSON_GetArraySize(jb) != out_f) {
            fprintf(stderr, "error: layer %d bias size mismatch\n", li);
            goto bad;
        }

        Layer *L = &layers[li];
        L->in_features = in_f;
